<?php
namespace App\Services\Marketing;
use App\Models\MarketingCampaign;
use Illuminate\Support\Facades\{DB,Crypt,Mail};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
final class MarketingEmailDelivery {
 public function listing(int $u,string $campaign):array {app(MarketingCampaigns::class)->query($u)->findOrFail($campaign);return DB::table('marketing_email_deliveries')->where('campaign_id',$campaign)->where('user_id',$u)->latest()->limit(20)->get()->map(fn($r)=>$this->view($r))->all();}
 private function view($r):array {[$name,$domain]=explode('@',Crypt::decryptString($r->recipient),2);return ['id'=>$r->id,'state'=>$r->state,'recipient'=>mb_substr($name,0,2).'***@'.$domain,'created_at'=>$r->created_at,'accepted_at'=>$r->accepted_at,'tracking_url'=>url('/m/r/'.$r->link_id),'error_code'=>$r->error_code];}
 public function prepare(int $u,string $campaign,array $d):array {
  abort_unless(config('marketing.email_test_enabled',false),409,'Email test sending is not enabled yet.');abort_unless(config('mail.default')==='smtp'&&filter_var(config('mail.from.address'),FILTER_VALIDATE_EMAIL),409,'A configured SMTP sender is required.');
  $origin=parse_url(config('app.url'));$target=parse_url($d['landing_url']);if(!filter_var($d['landing_url'],FILTER_VALIDATE_URL)||!in_array($target['scheme']??'',['http','https'],true)||isset($target['user'])||isset($target['pass'])||strtolower($target['host']??'')!==strtolower($origin['host']??'')||($target['port']??(($target['scheme']??'')==='https'?443:80))!==($origin['port']??(($origin['scheme']??'')==='https'?443:80)))throw ValidationException::withMessages(['landing_url'=>'Choose a landing page on this store.']);
  return DB::transaction(function()use($u,$campaign,$d){$c=app(MarketingCampaigns::class)->query($u)->lockForUpdate()->findOrFail($campaign);abort_unless($c->channel==='email'&&$c->status==='Draft',409,'Choose a saved Email Campaign draft.');abort_unless($c->version===(int)$d['version'],409,'This campaign changed. Reload before sending.');$email=mb_strtolower(trim($d['recipient']));$hash=hash_hmac('sha256',$email,config('app.key'));if(app(MarketingEmailUnsubscribe::class)->suppressed($c->merchant_key,$email))throw ValidationException::withMessages(['recipient'=>'This address has opted out of marketing emails.']);$old=DB::table('marketing_email_deliveries')->where('campaign_id',$c->id)->where('campaign_version',$c->version)->where('recipient_hash',$hash)->first();if($old)return ['delivery'=>$this->view($old),'reused'=>true];
   $t=app(MarketingContentTemplates::class)->query($u)->where('channel','email')->whereNull('archived_at')->find($c->channel_document['template_id']??null);abort_unless($t&&$t->version===($c->channel_document['template_version']??null),409,'The selected template changed. Save the campaign again before sending.');
   $link=(string)Str::uuid();$id=(string)Str::uuid();$tracking=url('/m/r/'.$link);$doc=$t->document;$subject=$c->channel_document['subject']??$doc['subject']??'';abort_unless(trim($subject)!=='',422,'Add an email subject.');$html=$doc['content_html']??'<p>'.e($doc['body']??'').'</p>';
   $values=['{{first_name}}'=>'Test recipient','{{last_name}}'=>'','{{email}}'=>$email,'{{store_name}}'=>app(\App\Support\ShopBrand::class)->name(),'{{unsubscribe_url}}'=>$unsubscribe=app(MarketingEmailUnsubscribe::class)->link($id,$c->merchant_key)];$html=strtr($html,array_map(fn($v)=>e($v),$values));$subject=strtr($subject,$values);
   $dom=new \DOMDocument();$previous=libxml_use_internal_errors(true);$dom->loadHTML('<?xml encoding="utf-8" ?>'.$html);libxml_clear_errors();libxml_use_internal_errors($previous);$linked=false;foreach($dom->getElementsByTagName('a') as $a){if($a->getAttribute('href')==='#'||$a->getAttribute('href')===$unsubscribe||str_contains(strtolower($a->textContent),'unsubscribe'))continue;$a->setAttribute('href',$tracking);$linked=true;break;}$html=$dom->saveHTML();if(!$linked)$html.='<p><a href="'.e($tracking).'">Visit website</a></p>';
   $html.='<p style="font:12px Arial;color:#637468"><a href="'.e($unsubscribe).'">Unsubscribe from marketing emails</a></p>';
   $html='<p style="font:12px Arial;color:#637468">Requested test email · No mailing-list subscription was created.</p>'.$html;
   DB::table('marketing_tracking_links')->insert(['id'=>$link,'campaign_id'=>$c->id,'post_id'=>null,'channel'=>'email','destination_id'=>$id,'merchant_key'=>$c->merchant_key,'user_id'=>$u,'post_version'=>$c->version,'destination_url'=>$d['landing_url'],'created_at'=>now(),'updated_at'=>now()]);
   DB::table('marketing_email_deliveries')->insert(['id'=>$id,'campaign_id'=>$c->id,'user_id'=>$u,'merchant_key'=>$c->merchant_key,'campaign_version'=>$c->version,'recipient'=>Crypt::encryptString($email),'recipient_hash'=>$hash,'state'=>'queued','link_id'=>$link,'snapshot'=>json_encode(['subject'=>'[TEST] '.$subject,'html'=>$html,'template_id'=>$t->id,'template_version'=>$t->version,'unsubscribe_url'=>$unsubscribe,'from_address'=>config('mail.from.address'),'from_name'=>config('mail.from.name')],JSON_THROW_ON_ERROR),'created_at'=>now(),'updated_at'=>now()]);
   \App\Jobs\SendMarketingTestEmail::dispatch($id);return ['delivery'=>$this->view(DB::table('marketing_email_deliveries')->find($id)),'reused'=>false];
  });
 }
 public function run(string $id):void {
  $row=DB::transaction(function()use($id){$merchant=DB::table('marketing_email_deliveries')->where('id',$id)->value('merchant_key');if(!$merchant)return null;$optout=app(MarketingEmailUnsubscribe::class);$optout->lock($merchant);$r=DB::table('marketing_email_deliveries')->where('id',$id)->lockForUpdate()->first();if(!$r||$r->state!=='queued')return null;$email=mb_strtolower(trim(Crypt::decryptString($r->recipient)));if($merchant!==app(\App\Services\Marketing\Audience\AudienceDirectory::class)->merchant()||$optout->suppressed($merchant,$email)){DB::table('marketing_email_deliveries')->where('id',$id)->update(['state'=>'blocked','error_code'=>'recipient_unsubscribed','updated_at'=>now()]);return null;}$owner=\App\Models\User::find($r->user_id);$snapshot=json_decode($r->snapshot,true);$bulk=($snapshot['kind']??'')==='bulk';$consent=true;if($bulk){$contact=app(\App\Services\Marketing\Audience\AudienceDirectory::class)->query()->where('id',$snapshot['contact_id']??'')->where('email',$email);$consent=app(\App\Services\Marketing\Audience\AudienceSegments::class)->eligible($contact,'email')->exists();$batch=DB::table('marketing_email_batches')->where('id',$snapshot['batch_id']??'')->where('merchant_key',$merchant)->where('user_id',$r->user_id)->first();$consent=$consent&&$batch&&$batch->confirmed_at&&$batch->state==='processing';}if(!$consent||config('mail.default')!=='smtp'||!config($bulk?'marketing.email_bulk_enabled':'marketing.email_test_enabled')||!\App\Domain\Marketing\MarketingPermission::allows($owner,\App\Domain\Marketing\MarketingPermission::MANAGE_CAMPAIGNS)){DB::table('marketing_email_deliveries')->where('id',$id)->update(['state'=>'blocked','error_code'=>'sending_unavailable','updated_at'=>now()]);return null;}$settings=app(MarketingEmailSettings::class);if($bulk&&!$settings->reserve($id,$snapshot['settings_version']??0)){DB::table('marketing_email_deliveries')->where('id',$id)->update(['error_code'=>'rate_limited','updated_at'=>now()]);return null;}$smtp=$bulk?$settings->raw():['host'=>config('mail.mailers.smtp.host'),'username'=>config('mail.mailers.smtp.username')];if(($smtp['host']??'')==='smtp.hostinger.com'&&filter_var($smtp['username']??'',FILTER_VALIDATE_EMAIL))$snapshot['bounce_address']=$smtp['username'];$snapshot['message_id']=app(MarketingEmailBounce::class)->messageId($r,$snapshot['from_address']);$r->snapshot=json_encode($snapshot,JSON_THROW_ON_ERROR);DB::table('marketing_email_deliveries')->where('id',$id)->update(['snapshot'=>$r->snapshot,'state'=>'sending','error_code'=>null,'updated_at'=>now()]);return $r;});if(!$row)return;
  try{$snapshot=json_decode($row->snapshot,true,512,JSON_THROW_ON_ERROR);$bulk=($snapshot['kind']??'')==='bulk';if($bulk){app(MarketingEmailSettings::class)->bindMailer();Mail::mailer('marketing_campaign')->to(Crypt::decryptString($row->recipient))->send(new \App\Mail\MarketingCampaignTestMail($snapshot));}else Mail::to(Crypt::decryptString($row->recipient))->send(new \App\Mail\MarketingCampaignTestMail($snapshot));DB::table('marketing_email_deliveries')->where('id',$id)->where('state','sending')->update(['state'=>'accepted','accepted_at'=>now(),'updated_at'=>now()]);}catch(\Throwable){$this->unknown($id);}
 }
 public function unknown(string $id):void{DB::table('marketing_email_deliveries')->where('id',$id)->whereIn('state',['queued','sending'])->update(['state'=>'unknown','error_code'=>'submission_unconfirmed','updated_at'=>now()]);}
}
